{
  "type": "function",
  "function": {
    "name": "issue_prorated_credit",
    "description": "Calculates and issues the prorated net credit for a canceled subscription, using the billing-cycle dates, plan price, and flat fee supplied in the request. Use this tool when the user requests a cancellation credit that must be calculated from those values; do NOT use it for refunds based on actual charges, usage-based billing, or discretionary adjustments. The credit is calculated in integer cents as `max(0, round_half_up(plan_price_cents * unused_days / total_days) - flat_fee_cents)`, where `total_days` is the number of calendar days in the billing cycle and `unused_days` is the number of calendar days from `cancel_date` through the day before `billing_end` (so the cancellation date itself is unused). Dates use ISO 8601 calendar format `YYYY-MM-DD`; the billing interval is `[billing_start, billing_end)`, and `cancel_date` must fall within that interval. Before submitting, calculate both day counts and the exact net credit; the tool validates the supplied calculation and issues no credit if the values do not match. This tool does not determine eligibility or override account policy."
    ,
    "strict": true,
    "parameters": {
      "type": "object",
      "properties": {
        "rationale": {
          "type": "string",
          "description": "Brief supporting explanation stating the calculated total billing days, unused days, and net credit in cents. Do not provide step-by-step reasoning."
        },
        "billing_start": {
          "type": "string",
          "description": "Billing-cycle start date in ISO 8601 calendar format `YYYY-MM-DD`; inclusive."
        },
        "billing_end": {
          "type": "string",
          "description": "Billing-cycle end date in ISO 8601 calendar format `YYYY-MM-DD`; exclusive. Must be later than `billing_start`."
        },
        "cancel_date": {
          "type": "string",
          "description": "Cancellation date in ISO 8601 calendar format `YYYY-MM-DD`; must satisfy `billing_start <= cancel_date < billing_end`. Count this date as unused."
        },
        "plan_price_cents": {
          "type": "integer",
          "description": "Nonnegative plan price for the full billing cycle, expressed as an integer number of cents (for example, 1299 means $12.99)."
        },
        "flat_fee_cents": {
          "type": "integer",
          "description": "Nonnegative flat fee to subtract from the prorated amount, expressed as an integer number of cents."
        },
        "total_days": {
          "type": "integer",
          "description": "Number of calendar days in the billing cycle: `(billing_end - billing_start)` in days using the half-open interval `[billing_start, billing_end)`. Must be a positive integer."
        },
        "unused_days": {
          "type": "integer",
          "description": "Number of unused calendar days: `(billing_end - cancel_date)` in days, counting `cancel_date` and excluding `billing_end`. Must be between 1 and `total_days`, inclusive."
        },
        "net_credit_cents": {
          "type": "integer",
          "description": "Exact nonnegative net credit in integer cents: `max(0, round_half_up(plan_price_cents * unused_days / total_days) - flat_fee_cents)`. Use round-half-up to the nearest cent before subtracting the flat fee."
        }
      },
      "required": [
        "rationale",
        "billing_start",
        "billing_end",
        "cancel_date",
        "plan_price_cents",
        "flat_fee_cents",
        "total_days",
        "unused_days",
        "net_credit_cents"
      ],
      "additionalProperties": false
    }
  }
}

