          "pattern": "^[A-Z]{3}$"
        },
        "weight_kg": {
          "type": "number",
          "description": "Freight weight in kilograms.",
          "exclusiveMinimum": 0
        },
        "depot_coordinates": {
          "type": "string",
          "description": "Latitude,longitude in decimal degrees, with exactly one comma and no space after it, for example 37.7749,-122.4194. Coordinates must be within valid latitude and longitude ranges.",
          "pattern": "^[+-]?\\d+(?:\\.\\d+)?,[+-]?\\d+(?:\\.\\d+)?$"
        },
        "carrier_note": {
          "type": ["string", "null"],
          "description": "Optional note for the carrier. Use null when no note is provided."
