{
  "type": "function",
  "function": {
    "name": "issue_prorated_credit",
    "description": "Issue a prorated net credit. Before calling, calculate every derived value using integer arithmetic and the rules below. Treat billing_start and billing_end as an inclusive-start, exclusive-end billing interval. Treat cancel_date as the first date not covered by service: unused_days = billing_end − cancel_date in calendar days; cycle_days = billing_end − billing_start in calendar days. Require billing_start <= cancel_date <= billing_end and billing_start < billing_end. Calculate gross_credit_cents by rounding plan_price_cents × unused_days ÷ cycle_days to the nearest cent, with exact half-cent ties rounded up. Calculate net_credit_cents = max(0, gross_credit_cents − flat_fee_cents). Submit all input dates, amounts, and the calculated unused_days and net_credit_cents. Amounts are nonnegative integer cents; dates use YYYY-MM-DD. Do not estimate or omit the derived values.",
    "strict": true,
    "parameters": {
      "type": "object",
      "properties": {
        "billing_start": {
          "type": "string",
          "format": "date",
          "description": "Inclusive first date of the billing cycle, YYYY-MM-DD."
        },
        "billing_end": {
          "type": "string",
          "format": "date",
          "description": "Exclusive end date of the billing cycle, YYYY-MM-DD."
        },
        "cancel_date": {
          "type": "string",
          "format": "date",
          "description": "Effective cancellation date and first date not covered by service; must be within the billing interval, including its exclusive end date."
        },
        "plan_price_cents": {
          "type": "integer",
          "minimum": 0,
          "description": "Full billing-cycle plan price in integer cents."
        },
        "flat_fee_cents": {
          "type": "integer",
          "minimum": 0,
          "description": "Flat fee to subtract from the rounded gross prorated credit, in integer cents."
        },
        "unused_days": {
          "type": "integer",
          "minimum": 0,
          "description": "Calculated calendar days from cancel_date up to, but not including, billing_end."
        },
        "net_credit_cents": {
          "type": "integer",
          "minimum": 0,
          "description": "Calculated credit in integer cents: max(0, round-half-up(plan_price_cents × unused_days ÷ cycle_days) − flat_fee_cents)."
        }
      },
      "required": [
        "billing_start",
        "billing_end",
        "cancel_date",
        "plan_price_cents",
        "flat_fee_cents",
        "unused_days",
        "net_credit_cents"
      ],
      "additionalProperties": false
    }
  }
}

