{
  "type": "function",
  "function": {
    "name": "issue_prorated_credit",
    "description": "Issue a prorated cancellation credit. Before calling, calculate the exact credit in integer cents and the unused billing days from the dates and amounts. Use calendar-day arithmetic: the billing cycle is [billing_start, billing_end), and the unused period is [cancel_date, billing_end). Thus, unused_days is the number of calendar days from cancel_date up to but not including billing_end; cancel_date must fall within the billing cycle. Compute credit_cents = round_half_up((plan_price_cents - flat_fee_cents) * unused_days / total_cycle_days), where total_cycle_days is the number of calendar days from billing_start up to but not including billing_end. Submit the calculated values, not an expression or an estimate. Do not call if dates are invalid, the cancellation date is outside the cycle, or the net amount is negative.",
    "parameters": {
      "type": "object",
      "properties": {
        "billing_start": {
          "type": "string",
          "format": "date",
          "description": "Inclusive start date of the billing cycle, in YYYY-MM-DD."
        },
        "billing_end": {
          "type": "string",
          "format": "date",
          "description": "Exclusive end date of the billing cycle, in YYYY-MM-DD; must be after billing_start."
        },
        "cancel_date": {
          "type": "string",
          "format": "date",
          "description": "Cancellation date, in YYYY-MM-DD; must be on or after billing_start and before billing_end."
        },
        "plan_price_cents": {
          "type": "integer",
          "minimum": 0,
          "description": "Full-cycle plan price in integer cents."
        },
        "flat_fee_cents": {
          "type": "integer",
          "minimum": 0,
          "description": "Flat fee to subtract from the plan price before prorating, in integer cents."
        },
        "unused_days": {
          "type": "integer",
          "minimum": 0,
          "description": "Calculated number of unused calendar days: billing_end minus cancel_date in days."
        },
        "credit_cents": {
          "type": "integer",
          "minimum": 0,
          "description": "Calculated net prorated credit in integer cents, rounded to the nearest cent with exact half-cent ties rounded up."
        }
      },
      "required": [
        "billing_start",
        "billing_end",
        "cancel_date",
        "plan_price_cents",
        "flat_fee_cents",
        "unused_days",
        "credit_cents"
      ],
      "additionalProperties": false
    },
    "strict": true
  }
}

