{
  "type": "function",
  "function": {
    "name": "issue_prorated_credit",
    "description": "Issues a customer credit for the unused portion of a billing cycle, less a flat fee. Use this tool when cancellation requires calculating and submitting a prorated credit from the cycle dates, plan price, and fee; do not use it for full refunds or credits that are not based on unused billing days. Before calling, calculate the cycle length, unused days, and net credit using the formulas in the parameter descriptions. The tool accepts dates as ISO 8601 calendar dates and monetary amounts as integer cents.",
    "strict": true,
    "parameters": {
      "type": "object",
      "properties": {
        "rationale": {
          "type": "string",
          "description": "Concise supporting explanation stating the date interval used and how the submitted unused-day count and net credit were calculated; do not provide hidden chain-of-thought."
        },
        "billing_start": {
          "type": "string",
          "description": "Billing cycle start date in YYYY-MM-DD format. The cycle includes this date."
        },
        "billing_end": {
          "type": "string",
          "description": "Billing cycle end date in YYYY-MM-DD format. This date is exclusive; billing_start must be earlier than billing_end."
        },
        "cancel_date": {
          "type": "string",
          "description": "Cancellation effective date in YYYY-MM-DD format, within the billing cycle's half-open interval [billing_start, billing_end). Unused days are the calendar days in [cancel_date, billing_end)."
        },
        "plan_price_cents": {
          "type": "integer",
          "description": "Full billing-cycle plan price in non-negative integer cents, before the flat fee."
        },
        "flat_fee_cents": {
          "type": "integer",
          "description": "Non-negative flat fee to subtract from the prorated gross amount, in integer cents."
        },
        "unused_billing_days_remaining": {
          "type": "integer",
          "description": "Calculated calendar-day count: (billing_end − cancel_date) in days, using the exclusive-end interval [cancel_date, billing_end). Must be between 0 and the full cycle length, where full cycle length is (billing_end − billing_start) in days."
        },
        "net_credit_cents": {
          "type": "integer",
          "description": "Exact non-negative net credit in integer cents. Calculate gross prorated cents as round-half-up(plan_price_cents × unused_billing_days_remaining ÷ full_cycle_days), where full_cycle_days = (billing_end − billing_start) in days; for non-negative integers this is floor((plan_price_cents × unused_billing_days_remaining + floor(full_cycle_days ÷ 2)) ÷ full_cycle_days). Then calculate net_credit_cents = max(0, gross_prorated_cents − flat_fee_cents)."
        }
      },
      "required": [
        "rationale",
        "billing_start",
        "billing_end",
        "cancel_date",
        "plan_price_cents",
        "flat_fee_cents",
        "unused_billing_days_remaining",
        "net_credit_cents"
      ],
      "additionalProperties": false
    }
  }
}

